.building-level{display:flex;justify-content:space-between;gap:8px;font-size:8px;color:#8a7952;margin-bottom:7px}
.building-card .action-btn{width:100%;font-size:8px;white-space:normal}
.quest-card{padding:15px;border:1px solid #e8e1cf;border-radius:8px;background:linear-gradient(140deg,#fdfaf0,#fffefa);margin-top:10px}
