.tribulation .bolt{position:absolute;left:50%;top:-10%;width:4px;height:105%;background:linear-gradient(#fffdf0,#d9c979 35%,#f4e9b0 65%,#fff);box-shadow:0 0 22px 8px rgba(240,229,170,.75),0 0 60px 20px rgba(215,199,128,.35);transform:translateX(-50%) skew(-6deg);animation:tribBolt .9s ease-out both}
.tribulation .bolt.two{left:38%;width:2px;transform:translateX(-50%) skew(8deg);animation-delay:.18s;opacity:.7}
.tribulation .bolt.three{left:63%;width:2px;transform:translateX(-50%) skew(-3deg);animation-delay:.32s;opacity:.6}
.tribulation .trib-text{position:absolute;inset:0;display:grid;place-items:center;text-align:center;color:#fffdf0;font:600 30px var(--serif);letter-spacing:2px;text-shadow:0 2px 30px rgba(241,229,170,.8);animation:tribText .5s .45s ease both}
