.merchant-offer .offer-seal{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;border:1px solid #e2d4ac;background:#fbf5e3;color:#9e7b2d;font:18px 'Ma Shan Zheng',serif;margin-bottom:8px}
.merchant-offer h3{margin:0 0 4px;font:600 12px var(--serif)}
.merchant-offer p{margin:0 0 8px;color:#7f8a80;font-size:8px;line-height:1.45}
.merchant-offer .action-btn{width:100%;margin-top:auto;font-size:8px;white-space:normal}
.log-list{display:grid;gap:5px;margin-top:9px}
.log-line{padding:7px 9px;border-left:2px solid #d9c382;background:#fbf9f1;color:#888474;font-size:8px;line-height:1.5}

/* Codex, achievements, rankings, quests */
.codex-tabs-panel{margin-bottom:12px}
.achievement-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-top:12px}
.achievement{display:flex;gap:10px;align-items:flex-start;padding:11px;border:1px solid #e8e8df;border-radius:7px;background:#fffefa}
.achievement.unlocked{border-color:#c9dcc7;background:linear-gradient(145deg,#f2f8ee,#fffefa)}
.achievement.hidden-ach{opacity:.6;background:#f8f7f1}
.achievement-icon{width:26px;height:26px;flex-shrink:0;display:grid;place-items:center;border-radius:50%;border:1px solid #e2ddce;background:#f8f6ee;color:#a69d85;font-size:11px}
.achievement.unlocked .achievement-icon{border-color:#b9d2ba;background:#e6f1e4;color:#4b7559}
.achievement b{display:block;font-size:9px;color:#4d5b4e;margin-bottom:2px}
.achievement small{display:block;font-size:7px;color:#90998d;line-height:1.45}
.achievement .reward{color:#9a8352;font-weight:700}
.rank-list{display:grid;gap:5px;margin-top:11px}
.rank-row{display:flex;align-items:center;gap:11px;padding:9px 11px;border:1px solid #eceee6;border-radius:6px;background:#fffefa;font-size:9px;color:#7d877d}
.rank-row.me{border-color:#b9d2ba;background:#f2f8ee;color:#43634e;font-weight:700}
.rank-row .rank-no{width:24px;height:24px;display:grid;place-items:center;border-radius:50%;border:1px solid #e4e6dd;background:#f8f7f1;color:#9a9885;font-size:8px;font-weight:700;flex-shrink:0}
.rank-row:nth-child(1) .rank-no,.rank-row:nth-child(2) .rank-no,.rank-row:nth-child(3) .rank-no{border-color:#e0cd9b;background:#faf2dc;color:#a28545}
.rank-row .rank-name{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rank-row b{color:#58684f;font-size:9px}
.building-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:12px}
.building-card{padding:14px;border:1px solid #e8e8df;border-radius:8px;background:#fffefa}
.building-card h3{margin:0 0 3px;font:600 13px var(--serif);color:#3b5144}
.building-card p{margin:0 0 7px;color:#7f8a80;font-size:8px;line-height:1.45}
.building-level{display:flex;justify-content:space-between;gap:8px;font-size:8px;color:#8a7952;margin-bottom:7px}
.building-card .action-btn{width:100%;font-size:8px;white-space:normal}
.quest-card{padding:15px;border:1px solid #e8e1cf;border-radius:8px;background:linear-gradient(140deg,#fdfaf0,#fffefa);margin-top:10px}
.quest-card h3{margin:0 0 3px;font:600 14px var(--serif);color:#3e4d3f}
.quest-card .npc{font-size:7px;letter-spacing:.8px;color:#a08a51;font-weight:700;margin-bottom:6px}
.quest-card p{margin:0 0 8px;color:#7c887f;font-size:9px;line-height:1.55}
.quest-card .action-btn{white-space:normal}
.quest-progress{display:flex;justify-content:space-between;gap:8px;font-size:8px;color:#8a7952;margin-top:6px}

/* Daily challenges / tracker */
.daily-challenge-list{display:grid;gap:7px;margin-top:11px}
.daily-row{display:flex;align-items:center;gap:10px;padding:9px 11px;border:1px solid #eceee6;border-radius:6px;background:#fffefa}
.daily-row.done{border-color:#c9dcc7;background:#f2f8ee}
.daily-row .daily-check{width:22px;height:22px;flex-shrink:0;display:grid;place-items:center;border-radius:50%;border:1px solid #e2ddce;background:#f8f6ee;color:#b0a88f;font-size:9px}
.daily-row.done .daily-check{border-color:#b9d2ba;background:#e6f1e4;color:#4b7559}
.daily-row div{flex:1;min-width:0}
.daily-row b{display:block;font-size:9px;color:#4d5b4e}
.daily-row small{display:block;font-size:7px;color:#90998d;margin-top:1px}
.daily-row .action-btn{padding:5px 8px;font-size:7px}
.quest-tracker{display:flex;align-items:center;gap:12px;margin-top:10px;padding:10px 12px;border:1px solid #ece7d8;border-radius:7px;background:#fbfaf4}
.quest-tracker .quest-seal{width:30px;height:30px;flex-shrink:0;display:grid;place-items:center;border-radius:50%;border:1px solid #e2d4ac;background:#fbf5e3;color:#9e7b2d;font:16px 'Ma Shan Zheng',serif}
.quest-tracker div{flex:1;min-width:0}
.quest-tracker b{display:block;font-size:9px;color:#4d5b4e}
.quest-tracker small{display:block;font-size:7px;color:#90998d;margin-top:1px}

/* Rarity */
.rarity-common{--rarity:#87918a}
.rarity-rare{--rarity:#4d7fa8}
.rarity-epic{--rarity:#7a5fa8}
.rarity-legendary{--rarity:#b78b35}
.rarity-mythical{--rarity:#b05a61}
.rarity-heavenly{--rarity:#b78b35}
.rarity-divine{--rarity:#8a5aa8}
.rarity-tag{display:inline-block;font-size:7px;letter-spacing:1px;font-weight:700;color:var(--rarity,#8b7b58)}

/* Trial / battle animation */
.tribulation{position:fixed;inset:0;z-index:60;pointer-events:none;background:radial-gradient(circle at 50% 20%,rgba(240,236,204,.5),rgba(20,33,31,.82));animation:tribFade 2.1s ease both;overflow:hidden}

