    const factor = r.rarity === 'Divine' ? 1 + luck * .1 : r.rarity === 'Heavenly' ? 1 + luck * .07 : r.rarity === 'Rare' ? 1 + luck * .025 : 1;
    return { root: r, weight: r.weight * factor };
