- body 50+level*45 qi +5 stones
- spirit same
- qi 40+level*35 qi +8 stones.
Check includes `qi` path now. On rank %5 grant meridian point. show.

`tick`:
```
function tick() {
 state.totalSeconds += 1;
 const today = dayIndex();
 if (today !== state.dailyDate) { reset...; ensureDaily(); }
 const gained=rateFor(); state.qi+=gained; state.totalQi+=gained; state.qiToday+=gained;
 if(state.active) state.medSeconds++;
 state.stoneClock=(...)+1; if>=8 ...
 if (state.upgrades.array>0 && state.totalSeconds%20===0)...
 if (daoLevel('water')>=3 && !state.enemy && !state.world.active && !state.realms.boss) state.hp=min(max,hp+maxHp*.01)
 if (daoLevel('life')>=3 && (state.enemy||...)) hp+=maxHp*.005
 // event
 if (!state.worldEvent.id){ if(!next) next=120; if(totalSeconds>=next){ ev=pick; set ends; next=totalSeconds+300; showToast }}
 else if(Date.now()>ends){...}
 // fate auto
