  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  const started = Date.now();
  await page.goto('http://localhost:3002/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);

  const seen = new Set();
  for (const [view, sel, label] of actions) {
    if (!seen.has(view) && view !== 'modal') {
      seen.add(view);
      const nav = page.locator(`.nav-item[data-view="${view}"]`);
      if (await nav.count()) { await nav.first().click(); await page.waitForTimeout(100); }
    }
    if (view === 'modal' && !(await page.locator('#modalBackdrop').isVisible())) {
      console.log('SKIP (no modal)', label); continue;
    }
    const loc = page.locator(sel).first();
    const count = await loc.count();
    if (!count) { console.log('MISSING', label, sel); continue; }
    const disabled = await loc.isDisabled().catch(() => false);
    if (disabled) { console.log('DISABLED', label); continue; }
    try {
      await loc.click({ timeout: 2500 });
      await page.waitForTimeout(120);
      const toast = await page.locator('#toast').textContent().catch(() => '');
