  worldEvent: { id: null, ends: 0, next: 100000 }, story: { mercy: 1, npcMet: [] }, rankClaimDate: 0
};

const results = [];
function check(name, ok, detail) { results.push(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ' · ' + detail : ''}`); }

(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });

  // ---- A. fresh state smoke test ----
  {
    const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
    const page = await ctx.newPage();
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
    await page.goto('http://localhost:3002/index.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(300);
    const views = ['cultivate','paths','dao','combat','sect','techniques','expeditions','alchemy','inherit','forge','fate','ascension','codex'];
    for (const v of views) {
      await page.locator(`.nav-item[data-view="${v}"]`).click();
      await page.waitForTimeout(80);
      const active = await page.locator(`#view-${v}`).evaluate(el => el.classList.contains('active') && el.innerText.length > 0);
      check(`fresh view ${v}`, active);
    }
    check('fresh no errors', errors.length === 0, errors.join(' | '));
    const qi0 = await page.locator('#qiText').textContent();
    await page.locator('.nav-item[data-view="cultivate"]').click();
    await page.locator('#meditateBtn').click();
    await page.waitForTimeout(1400);
    const qi1 = await page.locator('#qiText').textContent();
    check('meditation gains qi', Number(qi1.replace(/,/g,'')) > Number(qi0.replace(/,/g,'')), `${qi0} -> ${qi1}`);
    const saved = await page.evaluate(() => JSON.parse(localStorage.getItem('stillwater-cultivator-v1') || '{}'));
    check('meditation persists', saved.active === true);
    await ctx.close();
  }

  // ---- B. seeded action test ----
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
  await ctx.addInitScript((s) => localStorage.setItem('stillwater-cultivator-v1', JSON.stringify(s)), seed);
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('http://localhost:3002/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  const readState = () => page.evaluate(() => JSON.parse(localStorage.getItem('stillwater-cultivator-v1') || '{}'));
  const click = async (sel, label) => {
    const loc = page.locator(sel).first();
    if (!(await loc.count())) { check(label, false, 'missing ' + sel); return false; }
    if (await loc.isDisabled().catch(() => false)) { check(label, false, 'disabled'); return false; }
    await loc.click({ timeout: 3000 });
    await page.waitForTimeout(200);
    return true;
  };
  const closeModal = async () => {
    if (await page.locator('#modalBackdrop').isVisible().catch(() => false)) {
      const c = page.locator('#modalBackdrop [data-action="close-modal"]').first();
      if (await c.count()) await c.click(); else await page.locator('#modalClose').click();
      await page.waitForTimeout(150);
    }
  };

  // breakthrough
  await page.locator('#breakthroughBtn').click();
  await page.waitForTimeout(150);
  check('breakthrough modal opens', await page.locator('#modalBackdrop').isVisible());
  const stageBefore = (await readState()).stage;
  await click('#modalBackdrop [data-action="attempt-break"]', 'attempt breakthrough');
  await page.waitForTimeout(300);
  await closeModal();
  const afterBreak = await readState();
  check('stage advances on forced breakthrough', afterBreak.stage === stageBefore + 1, `${stageBefore} -> ${afterBreak.stage}`);

  // dao
  await page.locator('.nav-item[data-view="dao"]').click();
  await page.waitForTimeout(150);
  await page.locator('#view-dao [data-action="tab"][data-tab="dao"]').click();
  await page.waitForTimeout(150);
  const daoBefore = (await readState()).dao.fire.xp;
  check('comprehend dao', await click('#view-dao [data-action="comprehend-dao"][data-id="fire"]', 'comprehend dao'));
  check('dao xp increases', (await readState()).dao.fire.xp > daoBefore);
  const ptsBefore = (await readState()).daoPoints;
  check('infuse dao', await click('#view-dao [data-action="infuse-dao"][data-id="fire"]', 'infuse dao'));
  check('dao points decrease', (await readState()).daoPoints === ptsBefore - 1);
  await page.locator('#view-dao [data-action="tab"][data-tab="roots"]').click();
  await page.waitForTimeout(150);
  const gradeBefore = (await readState()).root.grade;
  check('upgrade root', await click('#view-dao [data-action="upgrade-root"]', 'upgrade root'));
  check('root grade rises', (await readState()).root.grade === gradeBefore + 1);
  check('reroll root', await click('#view-dao [data-action="reroll-root"]', 'reroll root'));
  await closeModal();

  // combat: enemy, spell, art, flee
  await page.locator('.nav-item[data-view="combat"]').click();
  await page.waitForTimeout(150);
  await click('#view-combat [data-action="seek-enemy"]', 'seek enemy');
  check('enemy spawned', !!(await readState()).enemy);
  const hpBefore = (await readState()).enemy?.hp;
  check('cast sect spell', await click('#view-combat [data-action="cast-spell"]', 'cast sect spell'));
  check('spell damages enemy', ((await readState()).enemy?.hp ?? 0) < hpBefore || (await readState()).enemy === null);
  if ((await readState()).enemy) {
    const hp2 = (await readState()).enemy.hp;
    check('use art', await click('#view-combat [data-action="use-art"]', 'use art'));
    check('art damages enemy', ((await readState()).enemy?.hp ?? 0) < hp2 || (await readState()).enemy === null);
  }
  if ((await readState()).enemy) check('flee', await click('#view-combat [data-action="flee"]', 'flee'));
  check('enemy cleared after flee', (await readState()).enemy === null);

  // boss
  await page.locator('#view-combat [data-action="tab"][data-tab="boss"]').click();
  await page.waitForTimeout(150);
  check('challenge boss', await click('#view-combat [data-action="challenge-boss"][data-id="emberwyrm"]', 'challenge boss'));
  check('boss battle active', !!(await readState()).world.active);
  for (let i = 0; i < 60 && (await readState()).world.active; i++) {
    const ok = await page.locator('#view-combat [data-action="boss-attack"][data-style="body"]').first().click({ timeout: 2000 }).then(() => true).catch(() => false);
    if (!ok) break;
    await page.waitForTimeout(40);
  }
  const afterBoss = await readState();
  check('boss defeated', !afterBoss.world.active && afterBoss.world.defeated.emberwyrm === 1, `tier ${afterBoss.world.tier}`);
  check('boss tier unlocked', afterBoss.world.tier >= 2);
  await closeModal();

  // sect buildings
  await page.locator('.nav-item[data-view="sect"]').click();
  await page.waitForTimeout(150);
  await page.locator('#view-sect [data-action="tab"][data-tab="buildings"]').click();
  await page.waitForTimeout(150);
  const medBefore = (await readState()).sectBuildings.meditation;
  check('upgrade building', await click('#view-sect [data-action="upgrade-building"][data-id="meditation"]', 'upgrade building'));
  check('building level rises', (await readState()).sectBuildings.meditation === medBefore + 1);

  // secret realm fight to completion
  await page.locator('.nav-item[data-view="inherit"]').click();
  await page.waitForTimeout(150);
  await page.locator('#view-inherit [data-action="tab"][data-tab="realms"]').click();
  await page.waitForTimeout(150);
  check('enter realm', await click('#view-inherit [data-action="enter-realm"][data-id="grotto"]', 'enter realm'));
  check('realm boss active', !!(await readState()).realms.boss);
  for (let i = 0; i < 60 && (await readState()).realms.boss; i++) {
    const ok = await page.locator('#view-inherit [data-action="realm-attack"][data-style="body"]').first().click({ timeout: 2000 }).then(() => true).catch(() => false);
    if (!ok) break;
    await page.waitForTimeout(40);
  }
  const afterRealm = await readState();
  check('realm cleared', !afterRealm.realms.boss && (afterRealm.realms.cleared.grotto || 0) >= 1);
  await closeModal();

  // fate resolve
  await page.locator('.nav-item[data-view="fate"]').click();
  await page.waitForTimeout(150);
  await click('#view-fate [data-action="seek-fate"]', 'seek fate');
  const fate = await readState();
  if (fate.fate.pending) {
    const opt = await page.locator('#view-fate [data-action="resolve-fate"]').first();
    check('resolve fate option', await opt.count() > 0);
    if (await opt.count()) { await opt.click(); await page.waitForTimeout(250); }
    const afterFate = await readState();
    check('fate pending resolved', !afterFate.fate.pending, `log ${afterFate.fate.log.length}`);
    await closeModal();
  } else {
    check('fate pending resolved', false, 'no pending fate event');
  }

  // persistence: reload and compare
  const beforeReload = await readState();
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(400);
  const afterReload = await readState();
  check('state survives reload', afterReload.stage === beforeReload.stage && afterReload.world.defeated.emberwyrm === beforeReload.world.defeated.emberwyrm, `stage ${afterReload.stage}`);
  check('seeded run no errors', errors.length === 0, errors.join(' | '));

  console.log(results.join('\n'));
  console.log('\nFAILURES', results.filter(r => r.startsWith('FAIL')).length);
  await page.screenshot({ path: '/tmp/opencode/extra-final.jpg', type: 'jpeg', quality: 72 });
  await browser.close();
})();

