  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto('http://localhost:3002/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  const overflow = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: innerWidth, body: document.body.scrollWidth }));
  console.log('OVERFLOW', JSON.stringify(overflow));
  console.log('MOBILE NAV visible', await page.locator('.mobile-nav').isVisible());
  console.log('SIDEBAR visible', await page.locator('.sidebar').isVisible());
  const views = ['cultivate','paths','dao','combat','sect','techniques','expeditions','alchemy','inherit','forge','fate','ascension','codex'];
  for (const v of views) {
    await page.locator(`.mobile-nav [data-view="${v}"]`).click();
    await page.waitForTimeout(90);
    const o = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: innerWidth }));
