  }
  await page.locator('.mobile-nav [data-view="cultivate"]').click();
  await page.waitForTimeout(200);
  await page.screenshot({ path: '/tmp/opencode/mobile-home.jpg', type: 'jpeg', quality: 72 });
  await page.locator('.mobile-nav [data-view="combat"]').click();
  await page.waitForTimeout(250);
  await page.screenshot({ path: '/tmp/opencode/mobile-combat.jpg', type: 'jpeg', quality: 72 });
  console.log('ERRORS', errors.length ? errors.join(' | ') : 'none');
  await browser.close();
})();

