const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const now = Date.now();
const seed = {
  version: 2, qi: 50000, stones: 50000, stage: 25, active: false, totalSeconds: 400, totalQi: 20000, qiToday: 500, medSeconds: 120,
  completedTrips: 3, trip: { id: 'herbs', ends: now - 1000, notified: false }, upgrades: { sutra: 3, array: 2, body: 3, beast: 2, alchemy: 2, fortune: 2, dao: 2 },
  boosts: .1, dailyClaimed: false, dailyDate: 2, brews: 10, milestones: [], lastSeen: now,
  hp: 5000, maxHp: 5000, enemy: null, pathLevels: { body: 8, spirit: 8, qi: 8 },
  herbs: { herb: 40, root: 30, flower: 30, ore: 30, essence: 20, crystal: 20, beastCore: 10, voidDust: 10, relic: 10 },
  sectRep: 100, sectRank: 2, tripToday: 1, sectId: 'azure', sectTokens: 2000, mission: { id: 'hunt3', progress: 3 },
  equipment: { sword: { owned: true, level: 3 }, helmet: { owned: false, level: 0 }, gloves: { owned: true, level: 2 }, pants: { owned: true, level: 2 }, vest: { owned: true, level: 2 }, shoes: { owned: true, level: 2 } },
  wins: 3, root: { type: 'heaven', grade: 2, essence: 40, discovered: ['heaven', 'water'], rerolls: 1 },
  meridians: { opened: { lung: true, heart: true, liver: true, spleen: true, kidney: true, pericardium: true, stomach: true, triple: true }, points: 6 },
  dao: { sword: { xp: 200 }, fire: { xp: 200 }, water: { xp: 200 }, lightning: { xp: 200 }, space: { xp: 200 }, life: { xp: 200 } }, daoPoints: 4,
  taming: { beasts: {}, active: null, eggs: { common: 1, rare: 1, epic: 1, mythic: 1 }, food: 12 },
  inheritance: { discovered: ['swordtomb'], trials: { swordtomb: { 0: true, 1: true, 2: true } }, completed: [], artifacts: [], points: 2 },
  realms: { cleared: {}, keys: 5, boss: null },
  forge: { weapons: { ironwood: { owned: true, refine: 10, awakened: false }, emberfang: { owned: true, refine: 10, awakened: false } }, equippedWeapon: 'ironwood', equippedArtifacts: [null, null] },
  sectBuildings: { meditation: 2, garden: 1, beastpen: 1, formation: 1, armory: 1, library: 1 }, luckBonus: 5,
  fate: { pending: null, log: [], merchant: [], merchantDate: 0, maps: 3, fragments: 1, clock: 0, encounters: 0, luckBuff: 0, luckBuffUntil: 0 },
  world: { active: { id: 'emberwyrm', hp: 800, maxHp: 980, log: [], turn: 0, weaken: false }, defeated: {}, tier: 1 },
  rebirth: { count: 1, points: 10, upgrades: { qi: 1, attack: 1, luck: 0, dao: 0 }, world: 0 },
  achievements: {}, hiddenFound: [],
  quests: { active: { id: 'q1', npc: 'Sister Mei', name: "The Herbalist's Debt", req: 1, desc: 'Sister Mei needs five spirit herbs.', type: 'gather', key: 'herb', target: 5, reward: { stones: 80, root: 2 } }, completed: [], progress: { q1: 0 } },
  daily: { date: 2, list: [ { id: 'kill3', label: 'Defeat 3 spirit beasts', type: 'kill', target: 3, progress: 3, claimed: false, reward: { stones: 40, tokens: 3 } }, { id: 'dao1', label: 'Comprehend a Dao once', type: 'dao', target: 1, progress: 1, claimed: false, reward: { stones: 50, daoPoints: 1 } }, { id: 'trip1', label: 'Complete 1 expedition', type: 'trip', target: 1, progress: 1, claimed: false, reward: { stones: 60, ore: 1 } } ] },
  stats: { kills: 12, bosses: 0, tames: 0, dao: 3, brews: 10, trips: 3, realms: 0, tribulations: 2, crit: 2, chests: 1 },
  activeArts: ['cloudpalm', 'flameserpent'], breakBuff: 0,
  worldEvent: { id: null, ends: 0, next: 100000 }, story: { mercy: 1, npcMet: [] }, rankClaimDate: 0
};
const results = [];
const check = (n, ok, d) => results.push(`${ok ? 'PASS' : 'FAIL'} ${n}${d ? ' · ' + d : ''}`);
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
  await ctx.addInitScript((s) => { if (!localStorage.getItem('stillwater-cultivator-v1')) localStorage.setItem('stillwater-cultivator-v1', JSON.stringify(s)); }, seed);
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto('http://localhost:3002/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(400);
  const st = () => page.evaluate(() => JSON.parse(localStorage.getItem('stillwater-cultivator-v1') || '{}'));
  const click = async (sel, label) => {
    const l = page.locator(sel).first();
    if (!(await l.count())) { check(label, false, 'missing'); return false; }
    if (await l.isDisabled().catch(() => false)) { check(label, false, 'disabled'); return false; }
    await l.click({ timeout: 2500 }); await page.waitForTimeout(220); return true;
  };
  const nav = async v => { await page.locator(`.nav-item[data-view="${v}"]`).click(); await page.waitForTimeout(150); };
  const closeModal = async () => {
    if (await page.locator('#modalBackdrop').isVisible().catch(() => false)) {
      const c = page.locator('#modalBackdrop [data-action="close-modal"]').first();
      if (await c.count()) await c.click(); else await page.locator('#modalClose').click();
      await page.waitForTimeout(150);
    }
  };

  // daily claim
  await page.locator('#dailyClaim').click();
  await page.waitForTimeout(200);
  check('claim daily practice', (await st()).dailyClaimed === true);
  await page.locator('#dailyChallenges [data-action="claim-daily"]').first().click().catch(() => {});
  await page.waitForTimeout(200);
  check('claim daily challenge', (await st()).daily.list.some(t => t.claimed));

  // trip collect
  await nav('expeditions');
  check('collect trip', await click('#view-expeditions [data-action="collect-trip"]', 'collect trip'));
  check('trip cleared', (await st()).trip === null);

  // sect: join crimson and buy gear
  await nav('sect');
  const sectBefore = (await st()).sectId;
  check('join sect', await click(`#view-sect [data-action="join-sect"]:not([disabled])`, 'join sect'));
  check('sect changed', (await st()).sectId !== sectBefore, `${sectBefore} -> ${(await st()).sectId}`);
  await page.locator('#view-sect [data-action="tab"][data-tab="armory"]').click();
  await page.waitForTimeout(150);
  check('buy gear', await click('#view-sect [data-action="buy-gear"][data-id="helmet"]', 'buy gear'));
  check('gear owned', (await st()).equipment.helmet.owned === true);
  check('claim mission', await click('#view-sect [data-action="claim-mission"]', 'claim mission'));
  check('mission cleared', (await st()).mission === null);

  // quest claim
  await nav('codex');
  await page.locator('#view-codex [data-action="tab"][data-tab="quests"]').click();
  await page.waitForTimeout(150);
  const herbBefore = (await st()).herbs.herb;
  check('claim quest', await click('#view-codex [data-action="claim-quest"]', 'claim quest'));
  const afterQuest = await st();
  check('quest cleared and herbs spent', afterQuest.quests.active === null && afterQuest.herbs.herb === Math.max(0, herbBefore - 5));

  // taming
  await nav('combat');
  await page.locator('#view-combat [data-action="tab"][data-tab="tame"]').click();
  await page.waitForTimeout(150);
  let tamed = false;
  for (let i = 0; i < 12 && !tamed; i++) {
    const ok = await click('#view-combat [data-action="tame-beast"]:not([disabled])', 'tame beast ' + (i + 1));
    tamed = Object.keys((await st()).taming.beasts).length > 0;
    if (!ok) break;
  }
  check('tame beast', tamed, `${Object.keys((await st()).taming.beasts).length} beast(s)`);
  const beastId = Object.keys((await st()).taming.beasts)[0];
  if (beastId) {
    check('set active beast', await click(`#view-combat [data-action="set-beast"][data-id="${beastId}"]`, 'set beast'));
    check('active beast set', (await st()).taming.active === beastId);
  }

  // combat tab to tame > set-beast only appears in roster? toggle not needed
  // boss spell & art
  await page.locator('#view-combat [data-action="tab"][data-tab="boss"]').click();
  await page.waitForTimeout(150);
  const logBefore = ((await st()).world.active?.log || []).length;
  check('boss spell', await click('#view-combat [data-action="boss-spell"]', 'boss spell'));
  check('boss spell logged', ((await st()).world.active?.log || []).length > logBefore);
  const log2 = ((await st()).world.active?.log || []).length;
  check('boss art', await click('#view-combat [data-action="boss-art"]', 'boss art'));
  check('boss art logged', ((await st()).world.active?.log || []).length > log2);
  check('boss retreat', await click('#view-combat [data-action="boss-retreat"]', 'boss retreat'));
  check('boss cleared', (await st()).world.active === null);

  // realm spell/art
  await nav('inherit');
  await page.locator('#view-inherit [data-action="tab"][data-tab="realms"]').click();
  await page.waitForTimeout(150);
  check('enter realm', await click('#view-inherit [data-action="enter-realm"][data-id="grotto"]', 'enter realm'));
  const rlog = ((await st()).realms.boss?.log || []).length;
  check('realm spell', await click('#view-inherit [data-action="realm-spell"]', 'realm spell'));
  check('realm spell logged', ((await st()).realms.boss?.log || []).length > rlog);
  const rlog2 = ((await st()).realms.boss?.log || []).length;
  check('realm art', await click('#view-inherit [data-action="realm-art"]', 'realm art'));
  check('realm art logged', ((await st()).realms.boss?.log || []).length > rlog2);
  check('realm retreat', await click('#view-inherit [data-action="realm-retreat"]', 'realm retreat'));

  // forge awaken
  await nav('forge');
  check('awaken weapon', await click('#view-forge [data-action="awaken-weapon"][data-id="emberfang"]', 'awaken weapon'));
  check('weapon awakened', (await st()).forge.weapons.emberfang.awakened === true);

  // reincarnation
  await nav('ascension');
  check('open reincarnate', await click('#view-ascension [data-action="reincarnate"]', 'reincarnate'));
  const rebBefore = (await st()).rebirth.count;
  check('confirm reincarnate', await click('#modalBackdrop [data-action="reincarnate-confirm"]', 'reincarnate confirm'));
  await closeModal();
  const afterReb = await st();
  check('reincarnation happened', afterReb.rebirth.count === rebBefore + 1 && afterReb.stage === 0, `stage ${afterReb.stage} count ${afterReb.rebirth.count}`);
  check('permanent systems survive', afterReb.root.type === 'heaven' && Object.keys(afterReb.meridians.opened).length === 8);

  // ascension requires stage 25 after reset; seed directly not possible. test ascend on fresh context? skip.

  console.log(results.join('\n'));
  console.log('\nFAILURES', results.filter(r => r.startsWith('FAIL')).length);
  console.log('ERRORS', errors.length ? errors.join(' | ') : 'none');
  await page.screenshot({ path: '/tmp/opencode/edge-final.jpg', type: 'jpeg', quality: 70 });
  await browser.close();
})();

