const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1360, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('file://' + path.resolve('/home/runner/work/PlayGround/PlayGround/index.html'));
  await page.waitForTimeout(700);

  // Fresh save: only the basic sword should be purchasable; rank-gated gear locked.
  const armory = await page.evaluate(() => {
    document.querySelector('.nav-item[data-view="sect"]').click();
    document.querySelector('[data-tab-view="sect"][data-tab="armory"]')?.click();
    return document.querySelector('#view-sect')?.innerText || '';
  });
  console.log('ARMORY has Requires:', /Requires/.test(armory));

  const sect = await page.evaluate(() => {
    document.querySelector('[data-tab-view="sect"][data-tab="overview"]')?.click();
    return document.querySelector('#view-sect')?.innerText || '';
  });
  console.log('SECT stage gate shown:', /REQUIRES STAGE 4/.test(sect));

  const tech = await page.evaluate(() => {
    document.querySelector('.nav-item[data-view="cultivate"]').click();
    document.querySelector('[data-tab-view="cultivate"][data-tab="techniques"]')?.click();
    return document.querySelector('#view-cultivate')?.innerText || '';
  });
  console.log('TECH stage gate shown:', /REQUIRES STAGE/.test(tech));
  console.log('TECH qi growth copy:', /Base qi growth is 2\.5/.test(tech));

  const buildings = await page.evaluate(() => {
    document.querySelector('.nav-item[data-view="sect"]').click();
    document.querySelector('[data-tab-view="sect"][data-tab="buildings"]')?.click();
    return document.querySelector('#view-sect')?.innerText || '';
  });
  console.log('BUILDINGS stage gate shown:', /REQUIRES/.test(buildings));

  // Ranked-up save: gated gear becomes purchasable.
  const ranked = await page.evaluate(() => {
    const s = JSON.parse(localStorage.getItem('stillwater-cultivator-v1'));
    s.sectRank = 3; s.sectTokens = 9999;
    localStorage.setItem('stillwater-cultivator-v1', JSON.stringify(s));
    location.reload();
    return true;
  });
  await page.waitForTimeout(900);
  const armory2 = await page.evaluate(() => {
    document.querySelector('.nav-item[data-view="sect"]').click();
    document.querySelector('[data-tab-view="sect"][data-tab="armory"]')?.click();
    const btn = document.querySelector('[data-action="buy-gear"][data-id="vest"]');
    return { text: btn?.textContent, disabled: btn?.disabled };
  });
  console.log('VEST unlock at rank 3:', JSON.stringify(armory2));

  console.log('ERRORS', errors.length ? errors : 'none');
  await browser.close();
})();

