const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1360, height: 900 } });
  await ctx.addInitScript(() => {
    if (localStorage.getItem('seed-done')) return;
    localStorage.setItem('seed-done', '1');
    localStorage.setItem('stillwater-cultivator-v1', JSON.stringify({
      version: 2, qi: 5000, stones: 5000, stage: 8, active: true, sectRank: 3, sectTokens: 5000,
      upgrades: { sutra: 1 }, equipment: {}, herbs: {}, root: { type: 'fire', grade: 1, essence: 0, discovered: ['fire'], rerolls: 0 },
      meridians: { opened: {}, points: 2 }, dao: {}, lastSeen: Date.now()
    }));
  });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('file://' + path.resolve('/home/runner/work/PlayGround/PlayGround/index.html'));
  await page.waitForTimeout(900);

  const tech = await page.evaluate(() => {
    document.querySelector('.nav-item[data-view="techniques"]').click();
    return document.querySelector('#view-techniques')?.innerText || '';
  });
  console.log('TECH length', tech.length);
  console.log('TECH gates', (tech.match(/REQUIRES STAGE \d+/g) || []).slice(0, 6));
  console.log('TECH base copy:', /Base qi growth: 5\.2/.test(tech), tech.split('\n').filter(l => /Base qi growth/.test(l))[0]);

  const armory = await page.evaluate(() => {
    document.querySelector('.nav-item[data-view="sect"]').click();
    document.querySelector('[data-tab-view="sect"][data-tab="armory"]')?.click();
    const vest = document.querySelector('[data-action="buy-gear"][data-id="vest"]');
    const sword = document.querySelector('[data-action="buy-gear"][data-id="sword"]');
    return { vest: { text: vest?.textContent, disabled: vest?.disabled }, sword: { text: sword?.textContent, disabled: sword?.disabled } };
  });
  console.log('ARMORY rank3', JSON.stringify(armory));

  const buildings = await page.evaluate(() => {
    document.querySelector('[data-tab-view="sect"][data-tab="buildings"]')?.click();
    return Array.from(document.querySelectorAll('[data-action="upgrade-building"]')).map(b => ({ id: b.dataset.id, text: b.textContent, disabled: b.disabled }));
  });
  console.log('BUILDINGS rank3', JSON.stringify(buildings));

  console.log('ERRORS', errors.length ? errors : 'none');
  await browser.close();
})();
